SET NAMES utf8mb4;

DELETE FROM spawns WHERE room_id BETWEEN 7000 AND 7499;
DELETE FROM exits WHERE room_id BETWEEN 7000 AND 7499 OR (room_id = 4 AND dir = 'down');

 'You''ve just stepped into the most unlucky position in the whole of DikuMUD. The result of such a foolish act should be punished with death, you know. With an acceleration of approximately 9.82 metres per second per second, you are now descending the Abyss. What awaits you at the bottom will continue to be a mystery. Bye Cruel World. You''ve fallen, and you can''t get up!!!'),
(7199, 'The Edge of the Water',
 'The pool side is dimly lit up by your light. You can see absolutely nothing else nearby. The darkness here seems enormously oppressive. The air is damp and the rock on which you stand is slippery. The pool seems too dark to make anything clear. The rock can be climbed upwards from here.'),
(7200, 'The Treasury',
 'You are in a small but well equipped treasury. You can see some writing on the wall. The ceiling has a funny glow, which enables you to see. You can get back into the inner lair through the stone door which is east.'),
(7201, 'The inner Lair',
 'You are in a octagonal room with smooth purple stone walls. The floor is made from black stone. In the western wall you see a large black stone door.'),
(7202, 'The Lair',
 'On the floor you see a lot of human decay, like bones and skulls. You also see a lot of slime. On the wall is a torch sitting in its sconce. To the north are a wooden door.'),
(7203, 'The Lair',
 'On the floor you see a lot of human decay, like bones and skulls. You also see a lot of slime. On the wall is a torch sitting in its sconce.'),
(7204, 'The Lair',
 'On the floor you see a lot of human decay, like bones and skulls. You also see a lot of slime. On the wall is a torch sitting in its sconce.'),
(7205, 'The Lair',
 'On the floor you see a lot of human decay, like bones and skulls. You also see a lot of slime. On the wall is a torch sitting in its sconce.'),
(7206, 'The lair',
 'On the floor you see a lot of human decay, like bones and skulls. You also see a lot of slime. On the wall is a torch sitting in its sconce.'),
(7207, 'The lair',
 'On the floor you see a lot of human decay, like bones and skulls. You also see a lot of slime. On the wall is a torch sitting in its sconce.'),
(7208, 'The lair entrance',
 'You are in a dry part of the sewer. To the north is a wooden door, you can see some slime at the lower part of the door. You also see some skulls and some broken bones.'),
(7209, 'The crawlway',
 'You are in a narrow crawlway. You don''t notice anything interesting here.'),
(7210, 'The four-way junction',
 'You are in a sewer junction. To the north is a small hole, to the west is a narrow crawlway and to the east and south the sewer continues.'),
(7211, 'The small cave',
 'You are in a collapsed sewer drain, which now is more like a small cave.'),
(7212, 'The sewer drain',
 'You are in a dry sewer drain which bends to the north.'),
(7213, 'The sewer drain',
 'You are in a dry sewer drain which bends to the east.'),
(7214, 'The drain end',
 'You are at the end of the drain around you the sewer has collapsed, the only exit is west.'),
(7215, 'The half-wet drain',
 'You are in a sewer drain where the floor is covered with water. To the north it looks more dry, south however the drain runs down into some water.'),
(7216, 'Under water in the sewer',
 'You swim in some dirty water and is holding you breath. You''ll better continue before you drown. It is a good thing that you can hold your light above water-level.'),
(7217, 'The half-dry drain',
 'You are in a half-dry sewer drain. To the north the drain runs a little bit downwards into some water to the east you can see a small hole. To the west you see another drain.'),
(7218, 'The very small room',
 'You are in a very small room, it is pretty uninteresting.'),
(7219, 'A dry sewer drain',
 'You are in a dry but dirty sewer drain. The drain continues east and south.'),
(7220, 'A boring drain',
 'You are in yet another sewer drain.'),
(7221, 'The sewer drain',
 'You are in a sewer drain, there is nothing special in here, except for a loud echo.'),
(7222, 'The sewer drain',
 'You are in a drain, with some slimy water on the floor.'),
(7223, 'The sewer bend',
 'You find yourself in an ordinary sewer bend, which bend from west to north.'),
(7224, 'The sewer junction',
 'You stand in a junction of three sewer drains. You see some odd scratches on the pipe wall, as from a gigantic rat.North and south the sewer continues as usual, but west it looks a little strange.'),
(7225, 'The sewer',
 'You are in a sewer, where the slimy water runs down through a tiny hole. You see some odd scratches on the pipe wall, as from a gigantic rat. There is a sewer drain south.'),
(7229, 'The strange sewer',
 'You are in a very strange sewer indeed, there are some odd scratches on the pipe wall, as from a gigantic rat. And you can see a lot of organic decay like bones from animals AND humans. West the drain runs slightly upwards.'),
(7230, 'The damp sewer',
 'You are in a sewer drain with a funny damp substance on the floor, in the substance you see a lot of decay. You see some odd scratches on the wall, as from a gigantic rat. Both to the east and west the pipe seems to run down.'),
(7231, 'The strange sewer',
 'You are in an ordinary sewer except for a lot of scratches on the sewer wall, ad a lot of debris on the floor.'),
(7232, 'The sewer',
 'You are in a sewer with more scratches on the walls. And of course a whole lot of decay. The drain runs east and north.'),
(7233, 'The sewer drain',
 'You stand in in a sewer drain, you are able to see some kind of cave-like room. You see some odd scratches on the drain wall, as from a gigantic rat. The sewer leads south.'),
(7234, 'The rat''s lair',
 'You are in a little cave. You are able to see quite a lot of debris on the floor. There is a sewer drain west of here.'),
(7279, 'The Wall of the Abyss',
 'You hang onto some steps leading down into utter darkness. There''s an exit leading up as well, though you''ll have to open the tiny rock again to do so.'),
(7280, 'The entrance',
 'You are in a very dark room. You notice that some faces are staring at you from inside the walls. In the middle of the room there is a small altar. To the north there is a small round door.'),
(7281, 'The corridor',
 'The corridor is glowing oppressively in a red hue. You can hear wailing through an open black hole to the east. To the south there is a round door.'),
(7282, 'The Realm of lost souls',
 'You are standing in nothing. All around you there are stars. Sometimes a shadow flies closely by you, wailing very loudly. To the north there is a small bright hole. To the west there is a small red hole.'),
(7283, 'The T-crossing',
 'You are in a small hallway. There are doors to the east and to the west. To the south there are a black hole. There is writing in the wall. Wails can be heard from the south.'),
(7284, 'The firedeath',
 'This room is very hot. There are flames surrounding you. You can see no exits at all! Skeletons are lying all over the floor.'),
(7285, 'The tortureroom',
 'You are standing in a middle of a square room. Along the walls skeletons are hanging in rusty chains. In the middle of the room there is a big metal box, covered with dust. To the south you can just make out a small exit.'),
(7286, 'The hells yard',
 'You are standing in a lot of mud. A disgusting smell surrounds the place, and makes you feel sick. Small flames sometimes shoot up from the hot mud. To the west there is a small door. To the north you can see an iron door.'),
(7301, 'The Entrance to the Realm of silence',
 'This is an utterly silent place. As you look around you see that there hasn''t been a living thing in a long time. The dust lies here in a thick layer on the floor and on the furniture. On the wall hangs a bleak and worn tapestry. A winding stone staircase leads up into darkness. On the wall to the west you can see a huge torch stuck into the solid rock. A large portcullis blocks your way to the north.'),
(7399, 'On the walls of the Abyss',
 'You are clutching the steps on the wall so that you don''t fall to the ground down below. A large sign says : I haven''t gotten any further ... Yet. But I''m pushing to get finished with this sewer. Greetings and Good Health :) Redferne The Gentle This stops your journey down, the only exit is up.'),
(7400, 'Cave entrance',
 'You are standing in the cave entrance. It is very dark down here. There is writing at the wall. There is an exit to the north. A stairway leads up.'),
(7401, 'Cave tunnel',
 'You are walking in a tunnel. It is very cold. You can feel the presence of a living thing ... SOMEWHERE.'),
(7402, 'Cave room',
 'You are standing in a room. It''s much cooler now. The walls are glowing.'),
(7403, 'Cave T-cross',
 'You are standing in a mud-like substance. The smell here is awful, it is rotten. To the west you can see some light.'),
(7404, 'Cave turning-point',
 'The mud are getting deeper. You are wondering, ''Would it be an idea to leave, before I disappear?''. To the south you notice a flat round stone are blocking the way. To the west you can see mud.'),
(7405, 'The secret room',
 'There is dust all over the place. It looks like nobody has been here for ages. In the middle of the room you see a socket with a crystal globe. The globe glows with a pulsing light. To the north you see a stone door. To the south you see a grey block.'),
(7406, 'The mudhole',
 'You are standing in a lot of mud. The mud goes to your chest. You feel the presence of something IN the mud. The only obvious exit is to the west.'),
(7407, 'Tunnel',
 'The mud goes to your knees. Otherwise the tunnel looks very normal.'),
(7408, 'The long tunnel',
 'Here There is almost no mud, as you stand at the top of a small rock. Just beside you there are a sign which says ''WARNING! The worms are dangerous!''.'),
(7409, 'The hot room',
 'You are very surprised, as this room for a change are hot instead of cold. To the north it goes downwards into some mud. There are also an exit to the west.'),
(7410, 'The small room',
 'As you look around you notice a small statue. There are exits to the west and to the east.'),
(7411, 'The stalagmite cave',
 'You are standing in a stalagmite cave. Water is dripping from the walls. It is very cold in here.'),
(7412, 'The stalagmite tunnel',
 'You have entered a small tunnel. Here it is quite dry. Maybe it would be an idea to rest here.'),
(7413, 'The spongy room',
 'You definitely NOT like this area. It is very dank, and most of the places it is wet.'),
(7414, 'The stalagmite T-cross',
 'You are standing in a cross. To the north you can see some light. Otherwise it is dark.'),
(7415, 'The blind end room',
 'This room is obviously a blind end. To the north you see a primitive picture.'),
(7416, 'The treasure room',
 'This room is rich ornamented. The walls has carves showing persons dancing around a sun which is drawn at the floor. It looks very old, and it is very dusty. To the south you see a secret door.'),
(7417, 'The square lair',
 'You are standing in the south-east part of the lair. You can see a skeleton lying at the wall.'),
(7418, 'The square lair',
 'You are standing in the north-east part of the lair. You see a sign at the wall'),
(7419, 'The square lair',
 'You are standing in the north-west part of the lair. Here''s another sign. There are a exit from the lair to the north.'),
(7420, 'The lair end',
 'You can see a table in front of you. It''s very dusty. Around the table five skeletons are siting. Exits are north and east.'),
(7421, 'East tunnel',
 'You are standing in dark tunnel, the exits are east and west. To the west you see a wooden door.'),
(7422, 'North tunnel',
 'You are standing in a dark tunnel, it leads upwards.'),
(7423, 'The L-shaped room',
 'You are standing in deep darkness. To the south there is a small exit. To the east you can see a gaping hole.'),
(7424, 'The Circular hall',
 'You are standing in round hall. To the north, east and south you can see a stone head hanging on the walls.'),
(7425, 'Dusty tunnel',
 'You are standing in dust. This place has not been touched for a long time. Otherwise it is quite boring here, looks like a place to rest! To the west you see the outline of a door. A tunnel leads to the east.'),
(7426, 'The crossing',
 'You are standing in a crossing of hallways. You can leave this place in every direction, except up and down. In the dust you notice strange footprints.'),
(7427, 'The L-shaped room',
 'You are standing in a L-shaped room. You can hear noises from the long tunnel to the east. You can feel fear! A sign is hanging on the wall.'),
(7428, 'Dragons lair',
 'You can see burned walls, the floorstones are fiery red. All kinds of bones are scattered all over the floor. On the walls you can see some burned shapes. You smell burned flesh. Two creatures are melted into the floor. You''re next.'),
(7429, 'The burned room',
 'You are in a room, which once had been quite burned. There is writing on the wall.'),
(7430, 'The wind tunnel',
 'You are standing in a tunnel. Above you, you can feel a breeze.'),
(7431, 'The glittering room',
 'This room are all bright. In the walls you can see some silver. Exits are: West, east and south.'),
(7432, 'The secret passageroom',
 'You have entered a tiny room. There WAS an exit down, and an exit to the west.'),
(7433, 'End of long tunnel',
 'You are at a end of a long tunnel. Right in front of you, you can see a grey mass. To the east you can see a tremendous long tunnel, but you know that, you has just been there.'),
(7434, 'Stair-room',
 'You are standing in a small room. Drawings of faces in pain are on the walls. You can feel that darkness is ruling this place. there are two exits: south and down. You have a feeling the downward exit isn''t finished yet...'),
(7435, 'Dark tunnel',
 'You are standing in a dark tunnel. It continues to the north and to the south. Bones are spread on the floor'),
(7436, 'Entrance to lair',
 'The smell here is awful. To the south you can see some smoke. A tunnel leads north, and east.'),
(7437, 'North-eastern part of Basilisks cave',
 'It is hard to see here because of the smoke. To the north you can see barely see a small tunnel. Other exits are to the south and to the west.'),
(7438, 'South-eastern part of basilisks cave',
 'There are a very small hole in wall, from where the smoke are coming from. Otherwise it is pitch dark. Exits are north and west.'),
(7439, 'North-western part of basilisks cave',
 'You can see some hay spread on the floor. The smell is awful here, and it makes you feel sick. The basilisk sleeps here. Watch out ... Maybe it is not far away.'),
(7440, 'South-western part of basilisks cave',
 'You can see nothing but smoke.'),
(7441, 'The small cave',
 'You are standing in small cave. You can see some light in the end. Exits are north and south.'),
(7442, 'The northern end of the pool',
 'You have wet feet, you are standing in water. The water looks calm. You can see that it''s a big lake. Light seeps from the water.'),
(7443, 'The pool',
 'You are swimming in water. It is getting deep here. It is dark in this end.'),
(7444, 'The south end of the pool',
 'You standing in water up to you neck. You can only see water.'),
(7445, 'The pool',
 'You are swimming in DARKNESS. You feel something touching your right leg.'),
(7001, 'The muddy sewer',
 'You are standing in mud to your knees. This is not the kind of place for a picnic. The muddy sewer stretches further into the south.'),
(7002, 'The muddy sewer junction',
 'The muddy sewer stretches into the dark to the south. It looks as if no person has ever sat his foot here before. It''s too muddy for that anyway. The sewer leads north, south and east from here.'),
(7003, 'The mudhole',
 'You stand in mud all the way up to your thighs and it''s not too comfortable since you are used to a somewhat different environment. The sewer leads to the north of here. In the middle you can just make out an enormous drainpipe leading down.'),
(7004, 'The Dark Pit',
 'You are standing by the edge of a dark pit that leads down into even deeper darkness. >BWWAAADDRR< - The smell from down there is unbearable. The sewer stretches into the darkness to the east.'),
(7005, 'The muddy sewer',
 'You are standing in the middle of a bend of the sewer pipe. It is very dark around here and the mud is sticking to your legs, not very pleasant. The pipe leads east and south from here.'),
(7006, 'The muddy sewer',
 'You are standing in something that reminds you very much of porridge, this has the advantage that it''s not hot, it''s rather cold actually. The pipe bends to the north and east.'),
(7007, 'The muddy sewer bend',
 'This isn''t your idea of a place to stay too long. You''re in up to your knees in something that resembles mud, but you''re not quite sure. The bend in which you stand leads west and south.'),
(7008, 'A muddy intersection',
 'You have both your feet safely stuck in mud. It isn''t the mud that''s wrong it''s the smell, the sounds, the total darkness that surrounds you. Everything here is so depressing. The pipe leads on with a trail of thick mud to the north, east and south.'),
(7009, 'The Sewer Junction',
 'You stand in the middle of a huge junction of sewer pipes right under what you''d think was an air shaft. The sewer pipes lead to the north, south, east and west. It look quite impossible to force your way up.'),
(7010, 'A bend in sewer pipe',
 'You are in a bend in the sewer pipe. A strong smell seeps in from the north. The sewer goes north and east.'),
(7011, 'The muddy sewer pipe',
 'You have entered a kind of tube intersection that leads south, west and east. Your legs are covered in mud up to the knees. REAL yucky!'),
(7012, 'The bend in the Muddy sewer',
 'This is not your idea of a holiday. You stand in mud up to your knees. It''s absolutely inconceivable how all this mud could have been placed here. The pipe leads to the west and south.'),
(7013, 'A MUDDY intersection',
 'You wouldn''t want to know the true feeling of standing in this mud up to your hips. >BWAADR<. All that fills your mind right now is the dream of a hot bath. This is NOT very clean mud you know, remember you''re in the sewer! The pipes leads north, south and east.'),
(7014, 'Muddy sewer',
 'You stand in a bend of the pipe system of the sewer with mud up to your thighs. Contemplating a higher level of existence here would be utterly inappropriate, as the smell would keep any intelligent creature from even thinking of anything but getting away from this foul end of the WORLD. The bend goes from north to west.'),
(7015, 'The old well',
 'You are standing by an old and worn well from before this century. The sewer leads to the east from here and the well leads down into darkness. Metal bars implanted in the side of the well lead down as a ladder.'),
(7016, 'The ordinary bend',
 'You are in the middle of a bend in the pipe system of the sewer system, WHAT a place!!! The pipe leads to the south and the east.'),
(7017, 'The sewer junction',
 'You are in a junction that leads north, west and south.'),
(7018, 'The ordinary junction',
 'This looks like an ordinary junction, actually it seems very quiet here. The pipelines lead west, east and north.'),
(7021, 'A quiet pipe junction',
 'This is the kind of place to rest, though the smell could be a LOT better than this. The sewer goes east, north and west from here.'),
(7022, 'The odd room with smooth walls',
 'As you enter you hear a loud click from one of the walls ... and you fall and fall and fall ... . . . . ... And come to an abrupt end. THIS is strange indeed. There''s an arched entryway leading down.'),
(7024, 'The sewer',
 'You are standing in mud up to your ankles. This is an intersection with sewer pipes leading east, south and west.'),
(7025, 'Another intersection',
 'You have never seen anything so BORING...This is an intersection with pipes leading north, south and east.'),
(7026, 'A junction',
 'This one seems interesting, a big difference from all the other junctions. It seems cleaner than the rest of them. Weird. Something that looks like an air shaft leads upwards, but it looks far too slippery to climb. The pipes lead to the south, west and north.'),
(7028, 'The sewer junction',
 'You stand in a junction of sewer pipes leading north, east and west.'),
(7029, 'The Triple Junction',
 'You stand in the middle of a huge junction of concrete sewer pipes. The pipes lead into three different directions : east, south and west.'),
(7030, 'The Quadruple Junction Under the Dump',
 'You are standing in something that reminds you of an entry to an ant hive. There are enormous concrete pipes leading north, south, east and west. There''s also a metal ladder built into the concrete wall leading up through a layer of garbage.'),
(7031, 'A triple junction',
 'You stand in a junction with pipes leading west, north and east.'),
(7034, 'A bend in the sewer pipe',
 'You can look in two directions where the pipe leads : south and west.'),
(7035, 'The sewer pipe bend',
 'You can look in two different directions where the pipe goes : west and north.'),
(7036, 'The pit',
 'You stand in a section of a pipe that leads to a dead end. In the floor there''s a pit leading down. There are bars set in the side of the pit wall functioning as a ladder.'),
(7037, 'The round room',
 'As you enter the room it starts rotating - at first slowly, later faster and faster - You get totally confused as to where up and down are, but you are certain that the doorway is in the opposite direction of what it was when you entered. It now leads east. There was only this one exit.'),
(7038, 'The three way junction',
 'You are standing in a junction of pipes that lead west, east and south.'),
(7039, 'The Sewer Store Room',
 'You stand in a small room lit by a single torch set in the wall. The only way out of here is to the north.'),
(7041, 'The Shaft',
 'You are standing by the edge of a deep, dark shaft leading down. A single ladder is your tool to work your way down if you so wish. The sewer pipe leads south from here.'),
(7043, 'The Sewer Entrance',
 'You stand in the middle of a pipe that leads from north to south. Above you an air shaft leads up into sunlight. It seems totally impossible to go up that way.'),
(7044, 'The junction going three ways',
 'You are in a passageway in the pipes of the sewer system leading north, east and west.'),
(7045, 'The Sewer Room',
 'You are standing in a large room with chairs set in the walls. You have the feeling of being watched. To the south there''s an entry to a larger room. The room is lit by five torches, also set in the walls. To the west there is a doorway leading out to the sewers.'),
(7046, 'The Sewer room',
 'This is a Room with walls that glitters like gold though not quite like it. This is strange as it looks as if the glitter lights the whole room. It looks very bright. To the south the floor is covered with yucky water. The North leads to sort of a Guard Room.'),
(7047, 'The Pool in the Sewer',
 'You stand in water to your waist. To the north is the entrance to this room. A single door leads east.'),
(7048, 'The Sewers',
 'You stand in a dead end of the sewer. The only way out is south. You can see a shaft leading up but it looks too difficult to go up that way.'),
(7049, 'The junction',
 'You stand in a junction leading north, west and east.'),
(7050, 'The small room',
 'The only thing in this room of interest is a chair, and that''s tight to the rock floor. A doorway leads south and another leads east into darkness.'),
(7051, 'The Sewer pipe',
 'You are in what reminds you of a foul sewer, as if you liked being here! You can see two exits leading either north or south.'),
(7052, 'The Grand Sewer',
 'You are in a Grand Sewer Pipe. This stretches toward the south. It''s large indeed! A doorway leads to the east from here.'),
(7053, 'The South end of the Grand Pipe',
 'You stand in water to your knees. A doorway leads west from here. The Pipe stretches north.'),
(7055, 'The Edge of The Water Sewer',
 'You stand in a room where half of the floor is covered in water. The water leads east and a doorway leads west.'),
(7056, 'The Dark hallway',
 'You can''t see much of this, even with a light. The hallway goes into a passageway to the south. A doorway leads west.'),
(7057, 'The dark passageway',
 'You can''t see anything but the ground where you put your feet. The passageway seems to continue south and north.'),
(7058, 'The dark passageway',
 'You can''t see anything but the ground where you put your feet. The passageway seems to continue south and north.'),
(7059, 'The dark passageway',
 'You can''t see anything but the ground where you put your feet. The passageway seems to continue south and north.'),
(7060, 'The dark passageway',
 'You can''t see anything but the ground where you put your feet. The passageway seems to continue west and north. To the east there''s water covering the floor and that leads through an arched entry to a watery sewer.'),
(7061, 'The Watery Sewer Bend',
 'You can''t see anything but the water you''re in up to your hips. The sewer seems to bend and lead south and west.'),
(7062, 'The Watery sewer',
 'You can''t see anything but the water you''re in up to your hips. The sewer seems to lead south and north.'),
(7063, 'The Watery sewer',
 'You can''t see anything but the water you''re in up to your hips. The sewer seems to lead south and north.'),
(7064, 'The Watery Sewer Junction',
 'You can''t see anything but the water you''re in up to your hips. The sewer seems to lead into a junction going south, north and east.'),
(7065, 'The Watery sewer',
 'You can''t see anything but the water you''re in up to your hips. The sewer seems to lead south and north.'),
(7066, 'The Watery sewer junction',
 'You can''t see anything but the water you''re in up to your hips. The sewer seems to lead into a junction that goes north, south and east.'),
(7067, 'The Watery sewer',
 'You can''t see anything but the water you''re in up to your hips. The sewer seems to lead south and north.'),
(7068, 'The Watery sewer bend',
 'You can''t see anything but the water you''re in up to your hips. The sewer seems to bend and lead west and north.'),
(7069, 'A ledge by the dark pool',
 'You can''t see much here but the echo tells you that there''s quite a drop down. You can just make out a huge dark pool out there in the darkness, mostly because of the trickling of water. The water from the sewer actually washes over this ledge and makes it quite slippery. From here it drops, like a waterfall, into the pool far down.'),
(7070, 'A ledge by the dark pool',
 'You can''t see much here but the echo tells you that there''s quite a drop down. You can just make out a huge dark pool out there in the darkness, mostly because of the trickling of water. The water from the sewer actually washes over this ledge and makes it quite slippery. From here it drops, like a waterfall, into the pool far down. Under you there is a small fissure in the rock. It seems big enough to contain a few people.'),
(7099, 'The fissure under the ledge',
 'This is a small fissure in the solid rock. Under you lies the deep dark pool. The water trickles quietly down from the ledge above you. The water smells like the water in a sewer.'),
(7101, 'Under the mudhole',
 'You stand in a small room with a great big opening in the ceiling. From this opening there''s mud dripping down in large lumps. >YUCK<. You can smell the foul stench of the slimy sediment as you try not to get covered by the falling sludge. To the east there is an entryway leading out from here and it seems absolutely impossible to force the muddy descent.'),
(7102, 'Under the Dark Pit',
 'Nice place you found yourself. You stand in the middle of a room with only two exits, Up and East. A tall ladder is left here so that you can climb up through the Pit without the use of a rope.'),
(7103, 'A muddy bend in the sewer system',
 'You are standing in what looks like a bend in the pipe system of the sewer. The ''floor'' is covered completely by mud! This includes covering your legs up to your knees as well. The pipe leads west and south.'),
(7104, 'A junction in the sewer pipes',
 'You stand in the middle of what looks like a triple junction of pipes going east, west and north.'),
(7105, 'Down the old well',
 'You are dangling on the slippery sides of the old well leading down and up. The only secure point here is the metal bars that are cemented into the sides, the ones that you cling frantically to so that you don''t fall. Who knows how deep this well is?'),
(7106, 'The northwestern corner of the ledge',
 'You stand, swaying out from the ledge, with only a couple of inches of safe, solid ledge under your feet. The ledge continues to the east but not back south. It seems that the ledge is too narrow to turn on so you''ll have to continue forward.'),
(7107, 'The narrow ledge',
 'You are in the progress of walking all the way around the ledge since there''s no way of turning around on this all too narrow path. There IS another exit from here but that leads right into mid-air and with high probability of a free fall session afterwards.'),
(7108, 'The narrow ledge',
 'You are in the progress of walking all the way around the ledge since there''s no way of turning around on this all too narrow path. There IS another exit from here but that leads right into mid-air and with high probability of a free fall session afterwards.'),
(7109, 'The narrow ledge',
 'You are in the progress of walking all the way around the ledge since there''s no way of turning around on this all too narrow path. There IS another exit from here but that leads right into mid-air and with high probability of a free fall session afterwards.'),
(7110, 'The narrow ledge',
 'You are in the progress of walking all the way around the ledge since there''s no way of turning around on this all too narrow path. There IS another exit from here but that leads right into mid-air and with high probability of a free fall session afterwards.'),
(7111, 'The southwestern corner of the ledge',
 'This seems like a ledge that is a little broader than the one just to the north of here. The ledge seems to lead around some sort of Abyss of total darkness. The ledge seems to have an odd-looking edge here.'),
(7112, 'An odd intersection',
 'You stand in a rather odd intersection of pipes. The pipes actually don''t resemble pipes anymore. They look more like a real stone tunnel, or a passageway hewn directly into the rock. The ways from here lead north, east and west.'),
(7113, 'The narrow ledge going east to west',
 'You are in the process of walking all the way around the ledge since there''s no way of turning around on this all too narrow path. There IS another exit from here but that leads right into mid-air and with high probability of a free fall session afterwards.'),
(7114, 'Mid-air',
 'You''ve just stepped into the most unlucky position in the whole of Merc Mud. The result of such a foolish act should be punished with death, you know. With an acceleration of approximately 9.82 metres per second per second, you are now descending the Abyss. What awaits you at the bottom will continue to be a mystery. Bye Cruel World. You''ve fallen, and you can''t get up!!!'),
(7115, 'The Broad ledge',
 'You are standing on a ledge that seems quite a lot larger than the rest of the ledges. This one leads to the west and the east, plus it has an exit going to the south. Though you could jump into mid-air, but it probably wouldn''t be such a good idea. The way south is in utter darkness.'),
(7116, 'The northeastern corner of the ledge',
 'You stand, swaying out from the ledge, with only a couple of inches of safe, solid ledge under your feet. The ledge continues to the west and leads south from here into darkness.'),
(7117, 'The narrow eastern ledge',
 'You are in the progress of walking all the way around the ledge since there''s no way of turning around on this all too narrow path. There IS another exit from here but that leads right into mid-air and with high probability of a free fall session afterwards. And THAT is west of here so watch your step.'),
(7118, 'The narrow eastern ledge',
 'You are in the progress of walking all the way around the ledge since there''s no way of turning around on this all too narrow path. There IS another exit from here but that leads right into mid-air and with high probability of a free fall session afterwards. And THAT is west of here so watch your step.'),
(7119, 'The narrow eastern ledge',
 'You are in the progress of walking all the way around the ledge since there''s no way of turning around on this all too narrow path. There IS another exit from here but that leads right into mid-air and with high probability of a free fall session afterwards. And THAT is west of here so watch your step.'),
(7120, 'The narrow eastern ledge',
 'You are in the progress of walking all the way around the ledge since there''s no way of turning around on this all too narrow path. There IS another exit from here but that leads right into mid-air and with high probability of a free fall session afterwards. And THAT is west of here so watch your step. You also see a small opening to the east.'),
(7121, 'The southeastern corner of the ledge',
 'This seems like a ledge that is a little broader than the one just to the north of here. The ledge seems to lead around some sort of abyss of total darkness.'),
(7122, 'Under the pit',
 'You stand in a completely dark cavern leading west. The wall looks weird here.'),
(7123, 'Under The Shaft',
 'A ladder leads up from here to the Shaft. A small opening leads west from here.'),
(7129, 'The sewer line',
 'You are in a narrow part of the sewer. Down the sewer continues and to the north is the ledge.'),
(7130, 'The sewer pipe',
 'You are in an odd sewer pipe You see some odd scratches on the pipe wall, as from a gigantic rat. You can see some slimy water gently running down into a sewer drain, and north the drain continues.')
AS new
ON DUPLICATE KEY UPDATE name = new.name, description = new.description;

;

AS new
ON DUPLICATE KEY UPDATE name = new.name, ac = new.ac, hp = new.hp, initiative = new.initiative, attack = new.attack,
    attacks = new.attacks, to_hit = new.to_hit, damage = new.damage, cr = new.cr, xp = new.xp,
    str_save = new.str_save, dex_save = new.dex_save, con_save = new.con_save, int_save = new.int_save,
    wis_save = new.wis_save, cha_save = new.cha_save, damage_type = new.damage_type, extra_damage = new.extra_damage,
    extra_type = new.extra_type, resistances = new.resistances, immunities = new.immunities,
    vulnerabilities = new.vulnerabilities, size = new.size, type = new.type, perception = new.perception,
    aggressive = new.aggressive, speed = new.speed, reach = new.reach, shot = new.shot, shot_hit = new.shot_hit,
    shot_damage = new.shot_damage, shot_type = new.shot_type, shot_range = new.shot_range, shot_long = new.shot_long, gear = new.gear;

-- Spawns start long dead so each one appears, with rolled HP, the first time its room is read.
;

